"""Authenticated local API and background stream lifecycle."""
from __future__ import annotations

import json
import logging
import os
import secrets
import re
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from .bridge import Bridge
from .provider import Client, ProviderError
from .restream import Go2Rtc

LOG = logging.getLogger('md_parking_bridge')
OPTIONS = Path('/data/options.json')
TOKEN_FILE = Path('/data/bridge_api_token')
SESSION_FILE = Path('/data/provider_session.json')
PAIRING_FILE = Path('/data/pairing_complete')
APP = {'os': 'android', 'ver': '2.0.6'}
AUTH_URL = 'https://auth.mdparking.ru/v2/'


class State:
    def __init__(self) -> None:
        self.started_at=time.time(); self.lock=threading.RLock(); self.bridge=None
        self.last_failure=None; self.auth_state='not_authenticated'; self.paired=False
        try: self.options=json.loads(OPTIONS.read_text(encoding='utf-8'))
        except Exception: self.options={}
        self.pairing_enabled=bool(self.options.get('pairing_enabled',False))
        if not self.pairing_enabled: PAIRING_FILE.unlink(missing_ok=True)
        self.paired=PAIRING_FILE.exists()
        # Do not accept a persisted legacy endpoint from pre-0.2 add-on options.
        self.client=Client(AUTH_URL,APP,'mdparking','')
        if self.client.load_session(SESSION_FILE): self._activate_session(refresh=True)

    def _activate_session(self, refresh: bool = False) -> None:
        try:
            if refresh: self.client.refresh_session(); self.client.save_session(SESSION_FILE)
            bridge=Bridge(self.client,Go2Rtc(),int(self.options.get('refresh_before_expiry_seconds',15)))
            bridge.discover(); bridge.refresh_due(); self.bridge=bridge
            self.auth_state='authenticated'; self.last_failure=None
            if not getattr(self,'worker_started',False):
                self.worker_started=True; threading.Thread(target=self._loop,daemon=True).start()
        except Exception:
            self.auth_state='authentication_failed'; self.last_failure='provider session failed'; LOG.error('provider session activation failed')

    def _loop(self) -> None:
        while True:
            try:
                with self.lock: self.bridge.refresh_due()
            except Exception: self.last_failure='stream refresh failed'; LOG.error('stream refresh failed')
            time.sleep(5)

    def request_code(self, phone: str, object_id: str | None) -> str:
        normalized_object=object_id.strip() if object_id else None
        self.client.request_code(self._phone(phone),normalized_object)
        self.auth_state='code_requested' if normalized_object else 'object_required'
        return self.auth_state

    def authorize(self, phone: str, object_id: str, code: str) -> None:
        self.client.authorize(self._phone(phone),object_id.strip(),code.strip()); self.client.save_session(SESSION_FILE); self._activate_session()

    @staticmethod
    def _phone(value: str) -> str:
        digits=re.sub(r'\D','',value)
        if len(digits)==10: digits='7'+digits
        elif len(digits)==11 and digits.startswith('8'): digits='7'+digits[1:]
        if len(digits)!=11 or not digits.startswith('7'): raise ValueError('invalid phone format')
        return digits

    def diagnostics(self):
        return {'read_only':True,'auth_state':self.auth_state,'camera_count':len(self.bridge.cameras) if self.bridge else 0,'last_failure':self.last_failure,'uptime_seconds':int(time.time()-self.started_at)}


def handler_factory(state: State, token: str):
    class Handler(BaseHTTPRequestHandler):
        def _json(self,status: int,payload: object):
            body=json.dumps(payload).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
        def _authorized(self): return self.headers.get('Authorization') == f'Bearer {token}'
        def _body(self):
            length=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(length) or b'{}')
        def do_POST(self):  # noqa: N802
            if self.path == '/v1/pair':
                if not state.pairing_enabled or state.paired: self._json(HTTPStatus.CONFLICT,{'error':'pairing_unavailable'}); return
                state.paired=True; PAIRING_FILE.write_text('paired',encoding='utf-8'); LOG.info('one-time pairing completed'); self._json(HTTPStatus.OK,{'api_token':token}); return
            if not self._authorized(): self._json(HTTPStatus.UNAUTHORIZED,{'error':'unauthorized'}); return
            try:
                data=self._body()
                if self.path == '/v1/auth/request-code':
                    status=state.request_code(str(data['phone']),str(data['object_id']) if data.get('object_id') else None)
                    self._json(HTTPStatus.OK,{'status':status}); return
                if self.path == '/v1/auth/authorize': state.authorize(str(data['phone']),str(data['object_id']),str(data['code'])); self._json(HTTPStatus.OK,state.diagnostics()); return
                self._json(HTTPStatus.NOT_FOUND,{'error':'not_found'})
            except ProviderError as exc:
                LOG.warning('provider auth request failed: %s',exc.safe_code); self._json(HTTPStatus.BAD_REQUEST,{'error':'provider_auth_failed','reason':exc.safe_code})
            except (KeyError,ValueError) as exc:
                LOG.warning('provider auth request failed: invalid_input'); self._json(HTTPStatus.BAD_REQUEST,{'error':'provider_auth_failed','reason':'invalid_input'})
        def do_GET(self):  # noqa: N802
            if self.path == '/health': self._json(HTTPStatus.OK,{'status':'ok'}); return
            if not self._authorized(): self._json(HTTPStatus.UNAUTHORIZED,{'error':'unauthorized'}); return
            if self.path == '/diagnostics': self._json(HTTPStatus.OK,state.diagnostics()); return
            if self.path == '/v1/cameras':
                cameras=state.bridge.cameras.values() if state.bridge else []
                self._json(HTTPStatus.OK,{'cameras':[{'id':c.stream_name,'name':c.name,'stream_name':c.stream_name} for c in cameras]}); return
            self._json(HTTPStatus.NOT_FOUND,{'error':'not_found'})
        def log_message(self,fmt,*args): LOG.info('local_api '+fmt,*args)
    return Handler


def main():
    logging.basicConfig(level=logging.INFO,format='%(levelname)s %(name)s: %(message)s')
    token=os.environ.get('API_TOKEN','').strip()
    if not token:
        token=TOKEN_FILE.read_text().strip() if TOKEN_FILE.exists() else secrets.token_urlsafe(32)
        if not TOKEN_FILE.exists(): TOKEN_FILE.write_text(token,encoding='utf-8'); TOKEN_FILE.chmod(0o600)
    state=State(); ThreadingHTTPServer(('0.0.0.0',8099),handler_factory(state,token)).serve_forever()

if __name__ == '__main__': main()
